/**
 * R2.0 · Canonical Renderer Control Identity Declarations
 * -----------------------------------------------------------------------------
 * 职责：为 frontend-demo-optimized/ 的 canonical renderer 声明每个渲染控件对应
 *       的 entityKey / controlKey / UiEvent 映射，作为 R2a/R2b 接入 DOM 属性
 *       （data-entity-key / data-control-key / data-control-id）的前置对账源。
 *
 * 范围（12 页面族）：
 *   settings-general / source-management / webdav-config / sync-backup /
 *   bookshelf / book-detail / import-conflict-resolve / search-results /
 *   discover / rss / source-switch / about-restore-preview
 *
 * 数据来源：
 *   1. registry-backed 声明：从 R1.1 control-id-registry.json 投影，覆盖 12 页面族
 *      下已被 IC0 DOM 审计枚举的交互控件。
 *   2. r2.0-subcontrol 声明：R1.1 标记的 46 个 containsUnenumeratedSubcontrols
 *      设置行子控件（switch 28 / select 15 / stepper 2 / segment 1），由 R2.0
 *      从 d2-settings-sync-renderers.js 的 row.type 推断并赋予独立 entityKey。
 *
 * 不做的事（R2.0 边界）：
 *   - 不写 data-control-id / data-entity-key / data-control-key 到渲染输出 HTML（R2b）
 *   - 不重构 renderer 行为（switch 还是 span；segment/stepper 缺事件不补）
 *   - 不修改 R1.1 冻结的 schema/types/src-control-identity
 *
 * 生成基线：commit ac4740b（R1.1 已完成），2026-07-20
 * -----------------------------------------------------------------------------
 */

